// Reçoit les coils (topic "coils") puis les registres (topic "registres") lus dans l'automate
// et les met en forme pour l'IHM. Une sortie par widget.
const a = global.get('adr');
if (msg.topic === 'coils') { flow.set('co', msg.payload); return null; }
const co = flow.get('co');
if (!co || !a) return null;
const hr = msg.payload;

const signe = v => v > 32767 ? v - 65536 : v;          // entier signé (température)
const uHta = hr[a.HR_U_HTA] / 100;
const consigne = hr[a.HR_CONSIGNE] / 100;
const bandeMorte = hr[a.HR_BANDE_MORTE] / 100;
const haut = consigne * (1 + bandeMorte / 100);
const bas = consigne * (1 - bandeMorte / 100);

// Date et heure simulées
const cumul = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334, 365];
const noms = ['janv.', 'févr.', 'mars', 'avr.', 'mai', 'juin', 'juil.', 'août', 'sept.', 'oct.', 'nov.', 'déc.'];
const jour = hr[a.HR_JOUR];
let m = 0;
while (m < 11 && jour > cumul[m + 1]) m++;
const minutes = hr[a.HR_HEURE];
const deuxChiffres = n => String(n).padStart(2, '0');

const etat = {
    t: Date.now(),
    uHta, consigne, bas, haut,
    uHtb: hr[a.HR_U_HTB] / 10,
    charge: hr[a.HR_I_CHARGE],
    temperature: signe(hr[a.HR_TEMPERATURE]) / 10,
    date: (jour - cumul[m]) + ' ' + noms[m],
    heure: deuxChiffres(Math.floor(minutes / 60)) + ':' + deuxChiffres(minutes % 60),
    minutes, jour,
    prise: hr[a.HR_PRISE],
    priseVisee: hr[a.HR_PRISE_VISEE],
    etape: hr[a.HR_ETAPE],
    tempsRestant: hr[a.HR_TEMPS_RESTANT],
    nbManoeuvres: hr[a.HR_NB_MANOEUVRES],
    motDeVie: hr[a.HR_MOT_DE_VIE],
    modeAuto: co[a.CO_MODE_AUTO],
    enManoeuvre: co[a.CO_MANOEUVRE_EN_COURS],
    defaut: co[a.CO_DEFAUT_REGLEUR],
    blocage: co[a.CO_BLOCAGE],
    butee: co[a.CO_BUTEE]
};

// Les widgets de réglage ne reçoivent une valeur que si elle a changé
// (sinon on écraserait ce que l'opérateur est en train de taper)
const dernier = context.get('dernier') || {};
context.set('dernier', dernier);
const siChange = (cle, valeur) => {
    if (dernier[cle] === valeur) return null;
    dernier[cle] = valeur;
    return { payload: valeur };
};

return [
    { payload: etat },                                             // 0 tableau d'état, transformateur, vie réelle
    [{ topic: 'U HTA', payload: uHta },                            // 1 courbe de tension
     { topic: 'Bande haute', payload: haut },
     { topic: 'Bande basse', payload: bas }],
    { topic: 'Prise', payload: etat.prise },                       // 2 courbe de prise
    siChange('auto', co[a.CO_MODE_AUTO]),                          // 3 interrupteur AUTO / MANUEL
    siChange('vie', co[a.CO_VARIATIONS_AUTO]),                     // 4 interrupteur vie réelle
    siChange('consigne', consigne),                                // 5 à 8 réglages
    siChange('bande', bandeMorte),
    siChange('tempo1', hr[a.HR_TEMPO_1]),
    siChange('tempo2', hr[a.HR_TEMPO_2]),
    siChange('htb', etat.uHtb),                                    // 9 à 11 curseurs
    siChange('charge', etat.charge),
    siChange('jour', jour)
];

// Transforme l'action d'un widget (msg.topic) en écriture Modbus dans l'automate.
// fc 5 = écrire 1 coil, fc 6 = écrire 1 registre. Le 3e nombre est l'échelle (valeur Modbus = valeur x échelle).
const a = global.get('adr');
const T = {
    mode:     [5, a.CO_MODE_AUTO],
    vie:      [5, a.CO_VARIATIONS_AUTO],
    plus:     [5, a.CO_BP_PLUS],
    moins:    [5, a.CO_BP_MOINS],
    acquit:   [5, a.CO_ACQUITTEMENT],
    consigne: [6, a.HR_CONSIGNE, 100],
    bande:    [6, a.HR_BANDE_MORTE, 100],
    tempo1:   [6, a.HR_TEMPO_1, 1],
    tempo2:   [6, a.HR_TEMPO_2, 1],
    htb:      [6, a.HR_U_HTB, 10],
    charge:   [6, a.HR_I_CHARGE, 1],
    jour:     [6, a.HR_JOUR, 1]
};
const t = T[msg.topic];
if (!t) return null;
const valeur = t[0] === 5 ? !!msg.payload
                          : Math.max(0, Math.min(65535, Math.round(Number(msg.payload) * t[2])));
return { payload: { fc: t[0], address: t[1], value: valeur, quantity: 1, unitid: 1 } };
